CREATE TABLE IF NOT EXISTS cutover_identity(entry varchar(64) COLLATE utf8mb4_bin NOT NULL,legacy_id varchar(128) COLLATE utf8mb4_bin NOT NULL,biz_type varchar(32) NOT NULL,biz_id varchar(128) COLLATE utf8mb4_bin NOT NULL,request_hash char(64) NOT NULL,evidence varchar(255) NOT NULL,PRIMARY KEY(entry,legacy_id),UNIQUE KEY business_identity(entry,biz_type,biz_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS cutover_audit(run_id varchar(64) COLLATE utf8mb4_bin PRIMARY KEY,input_sha256 char(64) NOT NULL,auditor varchar(128) NOT NULL,state varchar(16) NOT NULL,progress int NOT NULL DEFAULT 0,evidence json NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
ALTER TABLE user_credit_account MODIFY balance decimal(18,2) NOT NULL,MODIFY opening_balance decimal(18,2) NOT NULL,MODIFY status varchar(16) NOT NULL,MODIFY version bigint NOT NULL,MODIFY audit_source varchar(255) NOT NULL;
ALTER TABLE raffle_activity_account MODIFY total_remaining bigint NOT NULL,MODIFY day_limit bigint NOT NULL,MODIFY month_limit bigint NOT NULL,MODIFY effective_draw_count bigint NOT NULL,MODIFY opening_total bigint NOT NULL,MODIFY opening_day_limit bigint NOT NULL,MODIFY opening_month_limit bigint NOT NULL,MODIFY opening_effective_count bigint NOT NULL,MODIFY audit_source varchar(255) NOT NULL;
ALTER TABLE raffle_activity_account_day MODIFY business_date date NOT NULL,MODIFY quota_limit bigint NOT NULL,MODIFY remaining bigint NOT NULL,MODIFY opening_quota bigint NOT NULL,MODIFY audit_source varchar(255) NOT NULL;
ALTER TABLE raffle_activity_account_month MODIFY business_month char(7) NOT NULL,MODIFY quota_limit bigint NOT NULL,MODIFY remaining bigint NOT NULL,MODIFY opening_quota bigint NOT NULL,MODIFY audit_source varchar(255) NOT NULL;
